SKILLS_ZH["2122077892838314338:motion-design-skills"] = {"title": "motion-design-skills：按节奏排版和品牌做动效", "summary": "仓库说明：可安装的动效基础技能，覆盖时间、排版、颜色、构图，以及 After Effects、Remotion、标志和背景。安装：npx skills add iart-ai/motion-design-skills。", "hook": "具名可装 · motion-design-skills", "category": "视频 / 设计", "skill_name": "motion-design-skills"}
SKILLS_ZH["2122072146411438294"] = {"title": "herdr：分栏跑通宵的编码Agent", "summary": "原帖的用法是先装 Herdr，再把技能交给 Claude Code，然后在项目里开分栏：一栏跑 Claude，旁边一栏跑 Codex，用来做通宵任务。仓库把它写成编码助手的运行时。安装：npx skills add herdrdev/herdr --skill herdr -g。", "hook": "具名可装 · herdr", "category": "开发工具", "skill_name": "herdr"}
SKILLS_ZH["2122055583968669900"] = {"title": "unlazy：把任务拆深以免Agent偷懒", "summary": "仓库说明：防止助手偷懒。核心是深度树，把任务拆到第 N 层，每一片叶子都拿到整项任务的时间预算，层数越深投入越多。用法示例是 /unlazy tree 5。安装：npx skills add Leonxlnx/unlazy。", "hook": "具名可装 · unlazy", "category": "开发工具", "skill_name": "unlazy"}
SKILLS_ZH["2122042327846006865"] = {"title": "remotion-dev-skills：按官方规矩写代码做视频", "summary": "Remotion 给 AI 编码助手维护的技能目录。原帖称有 13 个，建项目、排版和渲染都有现成规矩，不必每次重新教模型。安装：npx skills add remotion-dev/skills。", "hook": "具名可装 · remotion-dev-skills", "category": "视频 / 开发", "skill_name": "remotion-dev-skills"}
SKILLS_ZH["2122032041323876757"] = {"title": "hypit：可克隆参考片或从零写流程", "summary": "官方仓库是 hypit-ai/hypit。先装技能，第一次用时助手会准备可执行文件。克隆视频是最快入口，没有参考片也可以从零写流程。工具本身不另收座位费，模型和编程助手用你自己的账号。安装：npx skills add hypit-ai/hypit -g。", "hook": "具名可装 · hypit", "category": "视频", "skill_name": "hypit"}
SKILLS_ZH["2122029358382768271"] = {"title": "gta-vi-shorts-editing：按专业标准剪GTA短片", "summary": "非官方技能，与 Rockstar 无关。仓库说明用来把 GTA 6 短视频剪到可发布：核对过的脚本、配音、精确字幕、色彩和响度检查，以及上传前的复核。安装：npx skills add JokerHTML/gta-vi-shorts-editing。", "hook": "具名可装 · gta-vi-shorts-editing", "category": "视频", "skill_name": "gta-vi-shorts-editing"}
SKILLS_ZH["2121974001769574455"] = {"title": "ui-skills-root：给Agent套用产品设计范式", "summary": "一条命令装入免费的界面技能包。原帖称它收的是产品设计师和苹果式工作室的界面做法，再交给模型用。安装：npx skills add ibelick/ui-skills --skill ui-skills-root。", "hook": "具名可装 · ui-skills-root", "category": "设计 / 前端", "skill_name": "ui-skills-root"}
SKILLS_ZH["2121973517273153540"] = {"title": "codehygiene：本地小模型检查代码整洁", "summary": "一个编译好的小模型，用来看代码是否好读、是否整洁。原帖称约 42.8 万三值参数、不做梯度训练、CPU 上约 10 毫秒、体积约 11 KB。安装：npx skills add brianbell-x/codehygiene -g。", "hook": "具名可装 · codehygiene", "category": "开发工具", "skill_name": "codehygiene"}
SKILLS_ZH["2121956338746151192"] = {"title": "seo-skills：每天体检站点并拆抓取问题", "summary": "Illyism/seo-skills 给 Claude Code、Cursor 和 Codex 用。原帖称里面有 30 个技能，分成 5 组：seo-autopilot 会每天检查站点仓库健康并开修复 PR，seo-roast 会拆抓取和 robots.txt 的问题。安装：npx skills add Illyism/seo-skills。", "hook": "具名可装 · seo-skills", "category": "营销", "skill_name": "seo-skills"}
SKILLS_ZH["2121928732235460756"] = {"title": "chaojifeng-video-content-creator：从选题做到成片和文案", "summary": "中文视频流水线：选题、调研、口播稿、分镜，再清洗转写里的口水词和长停顿，按字幕时间戳排 HTML/GSAP 特效，最后出成片、字幕和发布文案。每个阶段有门禁产物，自动模式不会替你对外发布。安装：npx skills add mileson/chaojifeng-video-content-creator。", "hook": "具名可装 · chaojifeng-video-content-creator", "category": "视频", "skill_name": "chaojifeng-video-content-creator"}
SKILLS_ZH["2121928732235460756:image-to-psd"] = {"title": "image-to-psd：把角色立绘拆成分层PSD", "summary": "把一张角色立绘（PNG、JPG 或 SVG）拆成 19 个标准部件的分层 PSD，每层有独立像素和可编辑蒙版，方便接着做 2.5D 动画。安装：npx skills add link-ding/image-to-psd。", "hook": "具名可装 · image-to-psd", "category": "设计", "skill_name": "image-to-psd"}
SKILLS_ZH["2121928732235460756:antialgorithm"] = {"title": "antialgorithm：先点出平庸创意再避开", "summary": "对付创意里的平均脸：起名、文案、故事、游戏点子、海报或界面时，先让模型说出它最先想到的平庸选项，再按这个项目本身的理由避开。安装：npx skills add mankidev/antialgorithm。", "hook": "具名可装 · antialgorithm", "category": "内容创作", "skill_name": "antialgorithm"}
SKILLS_ZH["2121924977276699099"] = {"title": "agent-skills：搜索安装并更新Agent技能", "summary": "Vercel 开源的技能管理器。搜索、安装、更新、删除都走命令行。原帖称支持 Claude Code、Codex、Cursor 等 75 种以上的 Agent。安装：npx skills add vercel-labs/agent-skills。", "hook": "具名可装 · agent-skills", "category": "开发工具", "skill_name": "agent-skills"}
SKILLS_ZH["2121919808610664791"] = {"title": "BeautifulRust：教Agent写审并移植Rust", "summary": "教编码助手按地道写法来写、审查和移植 Rust，并附带实测过的 clippy 配置。原帖记分板写着：Claude Code 从 72/85 到 80/85，Codex CLI 从 53/85 到 76/85。安装：npx skills add morganlinton/BeautifulRust。", "hook": "具名可装 · BeautifulRust", "category": "开发工具", "skill_name": "BeautifulRust"}
SKILLS_ZH["2121917944925986874"] = {"title": "openfilm：把片子写成网页再本机剪", "summary": "让 Codex 或 Claude Code 把片子写成带 film.html 的网页，每个镜头用时间函数画出来，再在本机浏览器里的 Studio 里改。同一时刻必须永远画出同一画面。官方写明不依赖 Remotion 这类框架。安装：npx skills add openfilm/openfilm。", "hook": "具名可装 · openfilm", "category": "视频 / 开发", "skill_name": "openfilm"}
SKILLS_ZH["2121907812448014433"] = {"title": "diagram-design：画流程图并导出PNG", "summary": "让 Claude Code、Codex 把文字画成流程图、时间线或组织架构图，再导出 PNG 放进文档或幻灯片。它是给编码助手用的技能，不是独立网页，成图后要自己核对文字和连线。安装：npx skills add cathrynlavery/diagram-design。", "hook": "具名可装 · diagram-design", "category": "设计", "skill_name": "diagram-design"}
SKILLS_ZH["2121904368207495580"] = {"title": "claude-video：抽帧转写后把视频交给Claude", "summary": "给编码助手装的看视频技能。丢进视频后会下载、抽帧、转字幕再交给 Claude。可以按起止时间只看一段，并用最大帧数封顶。转写走本地 WhisperX。安装：npx skills add bradautomates/claude-video -g。", "hook": "具名可装 · claude-video", "category": "视频", "skill_name": "claude-video"}
SKILLS_ZH["2121893215624179885"] = {"title": "vibe-to-prod：把原型收成可交接的实现", "summary": "给设计和开发交接用。作者用来把已经确认过的前端原型收成可实现的代码，避免好看界面底下是开发接不过去的临时代码。安装：npx skills add manish-uxai/vibe-to-prod -y。", "hook": "具名可装 · vibe-to-prod", "category": "设计 / 前端", "skill_name": "vibe-to-prod"}
SKILLS_ZH["2121892825583202736"] = {"title": "stitch-skills：打通界面设计到前端实现", "summary": "Google Labs 放出的界面技能包。原帖列出的能力包括一句话生成或修改界面、把已有代码转回设计、管理颜色字体和组件、导出 React 与 React Native、把随手需求收成设计提示词、约束审美，以及从一句提示搭多页网站。兼容 Claude Code、Codex、Cursor 和 Gemini CLI。安装：npx skills add google-labs-code/stitch-skills。", "hook": "具名可装 · stitch-skills", "category": "设计 / 前端", "skill_name": "stitch-skills"}
SKILLS_ZH["2121889197191836019"] = {"title": "edit-timeline-studio：让Claude接着改视频时间线", "summary": "原帖的用法是先在浏览器里剪一条短口播，确认字幕和配音都在本地完成，再装这个技能，让 Claude Code 继续改时间线。安装：npx skills add MartinDelophy/ai-video-editor --skill edit-timeline-studio。", "hook": "具名可装 · edit-timeline-studio", "category": "视频", "skill_name": "edit-timeline-studio"}
SKILLS_ZH["2121887730904805586"] = {"title": "caveman：让Agent少说少读且代码仍准", "summary": "让 Claude Code、Codex 少说废话、少读废日志，同一处修复仍然成立。原帖引用仓库自测：同一个 React 重渲染问题从 63 token 降到 20 token。只想先试说话风格可以不装整套命令行。安装：npx skills add JuliusBrussee/caveman -g。", "hook": "具名可装 · caveman", "category": "开发工具", "skill_name": "caveman"}
SKILLS_ZH["2121881389427532242"] = {"title": "agent-traffic：分辨请求来自Agent还是人", "summary": "Mintlify 开源的请求分类技能。按整理过的 User-Agent、请求头和运营方公开的校验来源，把 HTTP 请求分成 agent、ai-crawler、crawler、bot、human 或 unknown，而不是只做子串匹配。安装：npx skills add mintlify/agent-traffic。", "hook": "具名可装 · agent-traffic", "category": "开发工具", "skill_name": "agent-traffic"}
SKILLS_ZH["2121879271610503278"] = {"title": "ex-ussr-kinship-research：按档案查前苏联家谱", "summary": "证据优先的家谱技能，面向前苏联材料：教堂簿、民事登记、军事档案、流放和强制劳工记录。每条结论要指到具体档案和页码，存档产物带 SHA-256。安装：npx skills add DenisSergeevitch/ex-ussr-kinship-research。", "hook": "具名可装 · ex-ussr-kinship-research", "category": "研究", "skill_name": "ex-ussr-kinship-research"}
SKILLS_ZH["2121878902977221081"] = {"title": "stack-diagram：按技术栈画出官方图标架构", "summary": "你说出一组技术栈，它画出带官方图标的架构图。成品是单个 HTML，字体和图标内联，断网也能渲染；亮色和暗色一起出。安装：npx skills add caru-ini/stack-diagram。", "hook": "具名可装 · stack-diagram", "category": "设计", "skill_name": "stack-diagram"}
SKILLS_ZH["2121876421861900622"] = {"title": "iphone-home-screen：整理主屏并先给出改动计划", "summary": "仓库说明：通过 USB 或 Wi-Fi 整理 iPhone 主屏，可以移动 App、新建和整理文件夹、找出已卸载的 App。真正写入手机前会先给出可审阅的计划。安装：npx skills add Dreamon-im/iphone-home-screen。", "hook": "具名可装 · iphone-home-screen", "category": "开发工具", "skill_name": "iphone-home-screen"}
SKILLS_ZH["2121837181761380656"] = {"title": "hallmark：避开千篇一律的AI页面", "summary": "给 Claude Code、Codex、Cursor 用的设计技能，用来拦住跑偏的界面审美。原帖称第二版带了五十个主题。安装：npx skills add nutlope/hallmark -g。", "hook": "具名可装 · hallmark", "category": "设计 / 前端", "skill_name": "hallmark"}
SKILLS_ZH["2121816260505731438"] = {"title": "ui-sdk：给界面补齐焦点选择和拖拽", "summary": "仓库说明：给编码助手用的界面行为库，包含键盘导航、焦点、选择、关闭、弹出层和拖拽。安装：npx skills add vercel-labs/ui --skill ui-sdk。", "hook": "具名可装 · ui-sdk", "category": "设计 / 前端", "skill_name": "ui-sdk"}
SKILLS_ZH["2121803259929100636"] = {"title": "logo-design-skill：按流程画出可测的矢量标志", "summary": "仓库说明：给 Claude、Gemini CLI、Codex 等用的标志设计技能，包含原则、流程、SVG 做法、测试工具，以及 1400 多个参考标志。安装：npx skills add kaankiziltug/logo-design-skill。", "hook": "具名可装 · logo-design-skill", "category": "设计", "skill_name": "logo-design-skill"}
SKILLS_ZH["2121765364078199117"] = {"title": "scientific-agent-skills：让Agent查文献并跑分子", "summary": "一套科研技能。原帖称共 177 个，让助手除了写代码还能查文献、跑分子相关流程。技能能跑代码，装之前要读 SKILL.md。安装：npx skills add K-Dense-AI/scientific-agent-skills。", "hook": "具名可装 · scientific-agent-skills", "category": "研究", "skill_name": "scientific-agent-skills"}
SKILLS_ZH["2121701182548726017"] = {"title": "motion-design-skill：按缓动和编排做界面动效", "summary": "LottieFiles 给编码助手的动效原则，覆盖时间、缓动、编排，以及改编到界面上的动画原则。安装：npx skills add LottieFiles/motion-design-skill。", "hook": "具名可装 · motion-design-skill", "category": "设计 / 视频", "skill_name": "motion-design-skill"}
SKILLS_ZH["2121701182548726017:hairline"] = {"title": "hairline：做会跟着指针的等距线稿", "summary": "仓库说明：给 React 和带 DOM 的页面做等距线稿人物，线条会跟着指针动。安装：npx skills add lucasmarkes/hairline。", "hook": "具名可装 · hairline", "category": "设计", "skill_name": "hairline"}
SKILLS_ZH["2121701182548726017:anatomy"] = {"title": "anatomy：画可交互的等距机械剖视图", "summary": "仓库说明：用来画真实机械和复杂系统的等距剖视插图，可生成 SVG，也能加 WebGL 着色，并做成可交互页面。安装：npx skills add wheresryan22/anatomy。", "hook": "具名可装 · anatomy", "category": "设计", "skill_name": "anatomy"}
SKILLS_ZH["2121699916523123072"] = {"title": "anatomy-reveal-skill：做成可拆解的等距展示片", "summary": "仓库说明：把实物画成由许多小零件组成的等距剖视图，再做成可拖拽拆解的页面，以及默认约 10 秒、可改比例的产品展示 MP4。安装：npx skills add annnguyentt/anatomy-reveal-skill。", "hook": "具名可装 · anatomy-reveal-skill", "category": "视频 / 设计", "skill_name": "anatomy-reveal-skill"}
SKILLS_ZH["2121436456522862650"] = {"title": "lanshu-html-ppt-templates：用HTML模板做成讲解视频", "summary": "先用现成 HTML 模板生成可播放的演示，再录屏变成视频，用来做知识讲解、数据演示或产品介绍，少从零写动效。流程是准备文字、选模板、让 Codex 生成 HTML、在浏览器播放后录屏。安装：npx skills add cclank/lanshu-html-ppt-templates。", "hook": "具名可装 · lanshu-html-ppt-templates", "category": "视频", "skill_name": "lanshu-html-ppt-templates"}

SKILLS_ZH["2122463954731766173"] = {"title": "markdown-viewer：在Markdown里画图和表格", "summary": "原帖说这套技能让编程助手直接在 Markdown 里画图和画表，Claude Code、Codex、Cursor 都能用。仓库说明覆盖图表、数据可视化和技术文档。安装：npx skills add markdown-viewer/skills。", "hook": "具名可装 · markdown-viewer", "category": "内容创作", "skill_name": "markdown-viewer", "install": "npx skills add markdown-viewer/skills", "repo": "markdown-viewer/skills"}
SKILLS_ZH["2122459567762346261"] = {"title": "stitch-skills：配合Stitch服务的设计技能", "summary": "仓库说明：配合 Stitch MCP 服务的 Agent Skills，兼容 Antigravity、Gemini CLI、Claude Code 和 Cursor。原帖是一次安装测试：整包装进空目录后得到 stitch-extract-design-md 等技能，但 code-to-design 仍指向错误的相对路径。安装：npx skills add google-labs-code/stitch-skills --all。", "hook": "具名可装 · stitch-skills", "category": "设计", "skill_name": "stitch-skills", "install": "npx skills add google-labs-code/stitch-skills --all", "repo": "google-labs-code/stitch-skills"}
SKILLS_ZH["2122457224689926600"] = {"title": "SkillEvaluator：评估技能质量和对结果影响", "summary": "原帖介绍英伟达的技能质检：质量门槛、语义重复检测、合成评测集，并看技能有没有改变 Agent 的实际表现。可以不配 API Key，用 pip 对技能目录跑 validate，也可以放进 CI，或装进 Claude Code、Codex。安装：npx skills add NVIDIA/SkillEvaluator。", "hook": "具名可装 · SkillEvaluator", "category": "开发工具", "skill_name": "SkillEvaluator", "install": "npx skills add NVIDIA/SkillEvaluator", "repo": "NVIDIA/SkillEvaluator"}
