SKILLS_ZH["2124862687809093784"] = {"title": "sprite-stacking：把四张视图切成精灵切片", "summary": "这条原帖是一份仓库备忘，其中 Sprite Stacking 一段写明需要 Node.js 22.20 或更高，以及 Python 3 的 Pillow 和 NumPy。命令行示例用 views_to_slices.py 把视图切成切片，可指定切片数并输出预览和 HTML。四张视图默认按比例识别，顺序不对时可以加 --order reading。安装：npx skills add danielwh2/sprite-stacking。仓库：danielwh2/sprite-stacking。", "hook": "具名可装 · sprite-stacking", "category": "游戏开发", "skill_name": "sprite-stacking", "install": "npx skills add danielwh2/sprite-stacking", "repo": "danielwh2/sprite-stacking"}
SKILLS_ZH["2124858524824182836"] = {"title": "comps-analysis：做可比公司的估值对照表", "summary": "原帖只写了安装和验证：先准备 Node.js 22.20 以上，再装 comps-analysis，并用 npx skills ls 确认列表里有它，调用前要读 SKILL.md、脚本和权限。仓库 SKILL.md 写明它做可比公司分析，包含经营指标、估值倍数和统计对照，输出表格；并写明有机构数据源时优先用那些来源，不要把网页搜索当主要数据源。安装：npx skills add anthropics/financial-services --skill comps-analysis。仓库：anthropics/financial-services。", "hook": "具名可装 · comps-analysis", "category": "研究", "skill_name": "comps-analysis", "install": "npx skills add anthropics/financial-services --skill comps-analysis", "repo": "anthropics/financial-services"}
SKILLS_ZH["2124854982226944218"] = {"title": "drama-skills：写出短而有人物口气的台词", "summary": "原帖把 zenstory-ai/drama-skills 列为写剧本时可先装的四个之一，特点是台词短、人物有口气。同一篇还介绍了一份 117 个短剧技能加 16 个开源平台的清单，按小说改编、分集大纲、钩子、审稿、分镜和视频提示词分类，并称做了对照：10 个剧本技能加一个不装技能的对照，同一题各写 3 次再盲评。原帖也写明实测里每集收尾钩子常常是对照组更出彩，大纲出来后钩子要自己再改。安装：npx skills add zenstory-ai/drama-skills。仓库：zenstory-ai/drama-skills。", "hook": "具名可装 · drama-skills", "category": "视频 / 短剧", "skill_name": "drama-skills", "install": "npx skills add zenstory-ai/drama-skills", "repo": "zenstory-ai/drama-skills"}
SKILLS_ZH["2124813213363830897"] = {"title": "frontend-design：避免做成模板感的界面", "summary": "原帖只写了安装和验证：先装 Node.js 22.20 以上，再装 frontend-design，用列表命令确认，新开一轮 Codex 再调用，并先读 SKILL.md、LICENSE 和附带文件。仓库 SKILL.md 写明：做新界面或改现有界面时，在审美方向、字体和布局上做有意的选择，避免看起来像模板默认样式。安装：npx skills add anthropics/skills --skill frontend-design。仓库：anthropics/skills。", "hook": "具名可装 · frontend-design", "category": "设计 / 前端", "skill_name": "frontend-design", "install": "npx skills add anthropics/skills --skill frontend-design", "repo": "anthropics/skills"}
